const express = require("express");
const db = require("../config/db");

const router = express.Router();

// GET /api/users - list all users
router.get("/", async (req, res) => {
  try {
    const [rows] = await db.query("SELECT * FROM users");
    res.json(rows);
  } catch (err) {
    console.error("Error fetching users:", err);
    res.status(500).json({ error: "Could not fetch users" });
  }
});

// POST /api/users - create a user
// Body: { "name": "carlos" }  (the ID is generated by MySQL)
router.post("/", async (req, res) => {
  const { name } = req.body;

  if (!name) {
    return res.status(400).json({ error: "name is required" });
  }

  try {
    // The ? is replaced safely by the value in the array (prevents SQL injection)
    const [result] = await db.query("INSERT INTO users (Name) VALUES (?)", [name]);
    res.status(201).json({ UserIDs: result.insertId, Name: name });
  } catch (err) {
    console.error("Error creating user:", err);
    res.status(500).json({ error: "Could not create user" });
  }
});

module.exports = router;
